const input = $input.first().json;
const body = input.body || {};
const { pago_id, accion, verificado_por, notas_verificacion } = body;

if (!pago_id || isNaN(Number(pago_id))) {
  throw new Error('pago_id requerido y debe ser numérico');
}
if (!['VERIFICADO', 'RECHAZADO'].includes(accion)) {
  throw new Error('accion debe ser VERIFICADO o RECHAZADO');
}

const pagoId = parseInt(pago_id);
const por = verificado_por ? String(verificado_por).replace(/'/g, "''") : 'Fla';
const notas = notas_verificacion ? String(notas_verificacion).replace(/'/g, "''") : null;

const query = `UPDATE pagos
SET estado = '${accion}',
    verificado_por = '${por}',
    verificado_at = CURRENT_TIMESTAMP,
    notas_verificacion = ${notas ? `'${notas}'` : 'NULL'},
    updated_at = CURRENT_TIMESTAMP
WHERE id = ${pagoId} AND estado = 'PENDIENTE_VERIFICACION'
RETURNING id, alumno_id, monto, estado, comprobante_url;`;

return [{ json: { query, pago_id: pagoId, accion } }];

const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const prev = $('Build Query Verificar').first().json;

if (rows.length === 0) {
  return [{ json: { skip: true, message: 'Pago no encontrado o ya no está pendiente de verificación' } }];
}

const pago = rows[0];

if (prev.accion !== 'VERIFICADO') {
  return [{ json: { skip: true, pago } }];
}

const query = `UPDATE alumnos
SET estado = 'ACTIVO',
    estado_pago = 'PAGADO',
    fecha_pago_ultimo = CURRENT_DATE,
    updated_at = CURRENT_TIMESTAMP
WHERE id = ${pago.alumno_id} AND estado = 'REGISTRADO'
RETURNING id, nombre, whatsapp, estado;`;

return [{ json: { query, pago } }];

const bqa = $('Build Query Alumno').first().json;

if (bqa.message) {
  return [{ json: { success: false, message: bqa.message } }];
}

const pago = bqa.pago;
const verifyStep = $('Build Query Verificar').first().json;

let alumno = null;
if (verifyStep.accion === 'VERIFICADO') {
  const alumnoRows = $input.all().map(i => i.json).filter(j => j && j.id && j.nombre);
  alumno = alumnoRows[0] || null;
}

return [{
  json: {
    success: true,
    message: verifyStep.accion === 'VERIFICADO' ? 'Pago verificado correctamente' : 'Pago rechazado',
    pago: {
      id: pago.id,
      alumno_id: pago.alumno_id,
      monto: pago.monto,
      estado: pago.estado
    },
    alumno
  }
}];
